/// Public-domain hymn arrangements from the Mutopia Project (mutopiaproject.org), stored as flat
/// "start pitch duration" triples in sixteenth-note beats. Upper is the top voice, lower is everything beneath it.
struct Carol {
    typealias Note = (pitch: UInt8, start: Double, beats: Double)

    let title: String
    let bpm: Double
    let upper: [Note]
    let lower: [Note]

    var totalBeats: Double { (upper + lower).map { $0.start + $0.beats }.max()?.rounded(.up) ?? 0 }

    init(title: String, bpm: Double, upper: String, lower: String) {
        self.title = title
        self.bpm = bpm
        self.upper = Carol.decode(upper)
        self.lower = Carol.decode(lower)
    }

    private static func decode(_ text: String) -> [Note] {
        let numbers = text.split(separator: " ").compactMap { Int($0) }
        return stride(from: 0, to: numbers.count - 2, by: 3).map {
            (UInt8(numbers[$0 + 1]), Double(numbers[$0]) / 16, Double(numbers[$0 + 2]) / 16)
        }
    }
}

